	p := dpapp.PageIndex{
		App: s.app,
	}
	body, enableBackgroundStreaming, err := p.GET(r)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling PageIndex.GET", err)
		return
	}
	genericHead := s.app.Head(r)

